#!/bin/bash
set -e

# Build the actual flatpak
flatpak-builder --repo=repo build/ --force-clean app/dev.muntashir.SlobDictGTK.yaml

# Read the version from constants.py generated by this release build.
shopt -s nullglob
CONSTANTS_FILES=(build/files/lib/python3.*/site-packages/slobdict/constants.py)
shopt -u nullglob
if [ "${#CONSTANTS_FILES[@]}" -ne 1 ]; then
  echo "Error: Expected one constants.py in the Flatpak Python site-packages; found ${#CONSTANTS_FILES[@]}" >&2
  exit 1
fi
CONSTANTS=${CONSTANTS_FILES[0]}
VERSION=$(sed -n 's/^version = "\([^"]*\)"/\1/p' "$CONSTANTS")
if [ -z "$VERSION" ]; then
  echo "Error: Could not read version from $CONSTANTS" >&2
  exit 1
fi

flatpak build-bundle repo/ SlobDictGTK-${VERSION}.flatpak dev.muntashir.SlobDictGTK
echo "Created SlobDictGTK-${VERSION}.flatpak"
